-- Comparativo anual: subcategorias e classificação por SKU (Shopee/ML). Só cria estrutura e vínculos; não toca em vendas.
create table if not exists public.commerce_sku_category_v1 (
  sku_norm text primary key,
  category_id bigint not null references public.commerce_categories(id),
  subcategory_id bigint references public.commerce_subcategories(id),
  source text not null default 'classificacao_2026_10_29',
  updated_at timestamptz not null default now()
);
alter table public.commerce_sku_category_v1 enable row level security;
revoke all on public.commerce_sku_category_v1 from public,anon,authenticated;
grant all on public.commerce_sku_category_v1 to service_role;
create index if not exists commerce_sku_category_v1_cat_idx on public.commerce_sku_category_v1(category_id, subcategory_id);

-- backup (as colunas estavam vazias, mas guardamos o estado antes)
create table if not exists public.commerce_products_cat_backup_20261029 as select id, category_id, subcategory_id from public.commerce_products;
alter table public.commerce_products_cat_backup_20261029 enable row level security;
revoke all on public.commerce_products_cat_backup_20261029 from public,anon,authenticated;

create temp table _subs(i int, cat text, sub text, slug text) on commit drop;

select c.id, s.sub, s.slug from _subs s join public.commerce_categories c on c.name=s.cat
on conflict do nothing;

create temp table _map(sku text, i int) on commit drop;

select m.sku, c.id, sc.id from _map m join _subs s on s.i=m.i
join public.commerce_categories c on c.name=s.cat
join public.commerce_subcategories sc on sc.category_id=c.id and sc.name=s.sub
on conflict (sku_norm) do update set category_id=excluded.category_id, subcategory_id=excluded.subcategory_id, updated_at=now();

-- vincula os produtos pela classificação do primeiro SKU
update public.commerce_products p set category_id=k.category_id, subcategory_id=k.subcategory_id, updated_at=now()
from (select distinct on (s.product_id) s.product_id, c.category_id, c.subcategory_id
      from public.commerce_product_skus s
      join public.commerce_sku_category_v1 c on c.sku_norm=upper(regexp_replace(s.sku,'[\s_]+','','g'))
      order by s.product_id, s.id) k
where p.id=k.product_id;
